INSERT INTO INT_SERVERFUNCTION (ID, NAME, DESCRIPTION, TYPE, CODE, JDBC_ID, PUBLIC_EXECUTION, CRON_EXPRESSION, CRON_INPUT_JSON, CREATED_BY) VALUES (110, 'hotPreenchPacotes', 'Pacotes do gestor.', 'SQL', 'SELECT d.*, gp.ID as GP_ID FROM DRIVERS d
     JOIN GESTOR_PACOTE gp ON gp.DRIVER_ID = d.ID
     WHERE gp.GESTOR_ID = {{gestorId}} AND d.TIPO_DRIVER = ''PACOTE'' AND d.ATIVO = ''true'' ORDER BY d.NOME', NULL, FALSE, NULL, NULL, 'sarah@mitralab.io');
